import{_t as e,it as t,n,rt as r}from"./chunks/framework.DD2lXFOM.js";var i=JSON.parse(`{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/introduction/index.md","filePath":"en/guide/introduction/index.md"}`),a={name:`en/guide/introduction/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h1><p>GraphVis is a graph visualization library built on top of <a href="https://pixijs.com/" target="_blank" rel="noreferrer">PixiJS</a>, focused on high-performance rendering and interaction for graph data. It supports smooth drawing of tens of thousands of nodes and edges, making it suitable for scenarios that need to present complex relationship networks, such as social network analysis, knowledge graphs, topological structures, flowcharts, and more.</p><h2 id="core-features" tabindex="-1">Core Features <a class="header-anchor" href="#core-features" aria-label="Permalink to “Core Features”">​</a></h2><ul><li><strong>High-performance rendering</strong>: Built on PixiJS&#39;s WebGL rendering pipeline, it easily supports real-time interaction with tens of thousands of nodes and edges.</li><li><strong>Multiple graph types</strong>: Supports directed, undirected, and mixed graphs to meet different relationship representation needs.</li><li><strong>Rich nodes and edges</strong>: Includes built-in node types such as circle, ellipse, rectangle, polygon, star, text, and image, as well as edge types such as straight lines, curves, and automatic edges.</li><li><strong>Flexible layouts</strong>: Integrates layouts such as <code>d3-force</code> and <code>random</code>, and supports custom extensions.</li><li><strong>Complete interaction events</strong>: Provides event listeners for pointers, mouse, touch, and drag on nodes, edges, and the stage, making it easy to implement interactions such as selection, hover, and linking.</li><li><strong>Themes and styles</strong>: Supports dynamic theme switching and can automatically generate color schemes based on a primary color.</li><li><strong>Extensible architecture</strong>: Register custom nodes, edges, layouts, and themes via the <code>register</code> method to easily extend the library&#39;s capabilities.</li></ul>`,4)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};